from math import gcd,lcm,isqrt
from fractions import Fraction as F
from .authoring import maker,finish
from .common import section
q=maker('integer-constraints',['factorization','divisibility','integer feasibility'])
p=[
q(1,r'How many ordered pairs of integers $(x,y)$ with $x>3,y>2$ satisfy $xy-2x-3y=6$?',6,[(3,'Identify pairs obtained by swapping factors.'),(12,'Count negative factor pairs despite the bounds.'),(4,'Omit the factor pairs containing one.'),(36,'Choose factors independently rather than requiring their product.')],[r'Adding 6 completes the product: $(x-3)(y-2)=12$.',r'Both factors are positive. Each positive divisor d of 12 gives exactly one ordered pair $(d+3,12/d+2)$.',r'The six divisors 1,2,3,4,6,12 give six solutions.'],['Complete a product using the two linear terms.','Translate the bounds on x and y into bounds on the factors.'],'Convert an integer equation into a divisor correspondence.',lambda:sum(x*y-2*x-3*y==6 for x in range(4,30) for y in range(3,30)),level=2),
q(2,r'How many pairs of positive integers $x\le y$ satisfy $1/x+1/y=1/6$?',5,[(9,'Count ordered pairs.'),(4,'Discard the equal pair.'),(6,'Include a nondivisor as a possible shifted factor.'),(18,'Include negative shifted factors.')],[r'Clearing denominators gives $xy=6x+6y$, hence $(x-6)(y-6)=36$.',r'The original equation forces x>6 and y>6. The condition x≤y means the first factor is at most 6.',r'The divisors 1,2,3,4,6 give five pairs, including (12,12).'],['Clear denominators and complete a product.','Account for the ordering condition and the square factor pair.'],'Count unordered reciprocal solutions with a bijection.',lambda:sum(F(1,x)+F(1,y)==F(1,6) for x in range(1,50) for y in range(x,50))),
q(3,r'How many pairs of nonnegative integers $(x,y)$ satisfy $7x+11y=148$?',2,[(1,'Keep only the smallest admissible y.'),(3,'Allow y beyond the nonnegative-x bound.'),(14,'Count all y in the interval without the congruence.'),(0,'Mistake a nonintegral intercept for nonexistence.')],[r'Reducing modulo 7 gives $4y\equiv1\pmod7$, so $y\equiv2\pmod7$.',r'Nonnegativity gives $0\le y\le13$, leaving y=2 or 9.',r'They yield x=18 or 7, respectively; both work.'],['Use a modulus to eliminate one variable.','Intersect the resulting residue class with the nonnegativity interval.'],'Combine a linear congruence with an exact bound.',lambda:sum(7*x+11*y==148 for x in range(22) for y in range(14))),
q(4,r'How many pairs of positive integers $x>y$ satisfy $x^2-y^2=180$?',3,[(9,'Accept factor pairs of opposite parity.'),(6,'Count both orders of each factor pair.'),(2,'Miss the pair with difference ten.'),(18,'Treat every divisor as a valid difference.')],[r'Write $(x-y)(x+y)=180$. The factors must have the same parity and the second must be larger.',r'They must both be even. Write them as 2a,2b, so ab=45 and a<b.',r'The pairs (1,45),(3,15),(5,9) give three solutions. Recovery is x=a+b,y=b-a.'],['Factor the difference of squares.','The sum and difference of two integers have the same parity.'],'Enforce parity in a factor-pair parametrization.',lambda:sum(x*x-y*y==180 for x in range(1,100) for y in range(1,x))),
q(5,r'For how many integers n is $n^2+5n+6$ a positive prime?',2,[(0,'Assume n is nonnegative.'),(1,'Consider only positive factors.'),(3,'Treat zero as prime.'),(4,'Allow both signs independently in consecutive factors.')],[r'Factor as $(n+2)(n+3)$. A positive prime is a product of integers only if one factor is 1 or -1.',r'For positive factors, n+2=1 gives n=-1 and value 2. For negative factors, n+3=-1 gives n=-4 and value 2.',r'The other placements produce zero or a negative product. Exactly two integers work.'],['A prime cannot split into two factors of magnitude greater than one.','Consider negative factor pairs as well as positive ones.'],'Use primality to exhaust signed factor possibilities.',lambda:sum(__import__('sympy').isprime(n*n+5*n+6) for n in range(-100,101)),method='Enumerate a wide interval; the factor proof excludes all remaining integers.'),
q(6,r'Positive integers x,y satisfy $x^2+xy=84$. What is the least possible value of x+y?',12,[(7,'Report x instead of x+y.'),(14,'Stop at the divisor x=6.'),(10,'Use a real-valued bound without integer attainability.'),(84,'Choose the smallest x instead of minimizing the quotient.')],[r'Factor as $x(x+y)=84$. Set s=x+y; then s=84/x and s>x.',r'Thus x divides 84 and $x^2<84$. The largest such divisor is 7.',r'This gives s=12 and y=5, proving the lower value is attained.'],['Treat x+y as a single factor.','To minimize the quotient, find the largest admissible divisor.'],'Optimize an integer expression using a divisor and a strict bound.',lambda:min(x+y for x in range(1,85) for y in range(1,85) if x*x+x*y==84)),
q(7,r'Positive integers x,y satisfy $xy=3x+4y$. What is the largest possible x+y?',20,[(14,'Select the most balanced factors, which minimize the sum.'),(19,'Subtract rather than add one of the shifts.'),(12,'Report the completed product.'),(21,'Use an inadmissible zero factor.')],[r'Complete the product: $(x-4)(y-3)=12$. Both factors must be positive: if both were negative, their magnitudes would be at most 3 and 2, whose product is at most 6.',r'For positive integer factors a,b with ab=12, their sum is largest for 1 and 12.',r'Then x+y=a+b+7=20, attained by (5,15) or (16,4).'],['Complete the product and justify the sign of its factors.','Compare sums of the possible positive factor pairs.'],'Prove a sign restriction before optimizing a factor sum.',lambda:max(x+y for x in range(1,50) for y in range(1,50) if x*y==3*x+4*y)),
q(8,r'How many nonnegative integer triples $(x,y,z)$ satisfy $x+y+z=12$, $x=2y+1$, and z is odd?',2,[(4,'Ignore the parity condition.'),(3,'Include a negative z.'),(6,'Choose y and z independently.'),(1,'Require y to be positive as well.')],[r'Substitution gives $3y+z=11$, so y is 0,1,2,or 3.',r'Because z is odd, $11-3y$ is odd and therefore y is even.',r'Only y=0 and y=2 work, giving (1,0,11) and (5,2,5).'],['Eliminate x before counting.','Use parity after finding the allowed interval for y.'],'Combine elimination, bounds, and parity.',lambda:sum(x+y+z==12 and x==2*y+1 and z%2==1 for x in range(13) for y in range(13) for z in range(13)),level=2),
q(9,r'A three-digit positive integer equals 11 times the sum of its digits. What is the integer?',198,[(99,'Allow a zero hundreds digit.'),(189,'Interchange the tens and units digits.'),(297,'Satisfy the digit sum but not the place-value equation.'),(108,'Lose one factor of ten in the digit equation.')],[r'Write the integer as 100a+10b+c. The condition reduces to $89a=b+10c$.',r'The right side is at most 99, so a=1. Then $b+10c=89$, giving c=8,b=9.',r'The number is 198, and 11(1+9+8)=198 verifies it.'],['Separate digits from their place values.','Use the maximum possible right side to determine the hundreds digit.'],'Use place-value algebra and a sharp digit bound.',lambda:next(n for n in range(100,1000) if n==11*sum(map(int,str(n))))),
q(10,r'How many pairs of positive integers $x\le y$ satisfy $x^2+y^2=325$?',3,[(6,'Count both orders.'),(2,'Miss the representation with one coordinate equal to one.'),(4,'Include an endpoint with a zero coordinate.'),(5,'Count values passing a residue test without checking squares.')],[r'The ordering gives $1\le x\le\lfloor\sqrt{325/2}\rfloor=12$.',r'For these twelve x values, $325-x^2$ is a square only at x=1,6,10, producing y=18,17,15.',r'There are three pairs. Squares modulo 5 first restrict x and y to one divisible by 5 or both residues ±1 and ±2; the finite square check completes the proof.'],['Bound the smaller variable before searching.','A residue condition can eliminate candidates but cannot prove the remainder is a square.'],'Finish a bounded Diophantine search without confusing necessity with sufficiency.',lambda:sum(x*x+y*y==325 for x in range(1,19) for y in range(x,19))),
q(11,r'How many pairs of positive integers $(x,y)$ satisfy $x^2+y^2=3xy$?',0,[(1,'Count the excluded zero pair.'),(2,'Assume symmetry guarantees a pair.'),(3,'Accept residues without an actual integer solution.'),(6,'Confuse a homogeneous equation with a finite list of ratios.')],[r'Modulo 3, a square is 0 or 1. Since $x^2+y^2\equiv0$, both x and y must be divisible by 3.',r'Divide both by 3. The resulting smaller positive pair satisfies the same equation.',r'If a solution existed, choose one minimizing x+y. The smaller pair contradicts minimality, so no positive solution exists.'],['Reduce the equation modulo a small prime.','If both variables share a forced factor, divide it out and compare sizes.'],'Turn a modular obstruction into infinite descent.',lambda:sum(x*x+y*y==3*x*y for x in range(1,301) for y in range(1,301)),method='Bounded search checks examples; the minimal-positive-sum argument proves nonexistence for all integers.'),
q(12,r'How many ordered pairs of positive integers have gcd 6 and lcm 180?',8,[(4,'Identify reversed ordered pairs.'),(16,'Split prime powers between both coprime factors.'),(30,'Use the quotient as the count.'),(12,'Count all divisors without the coprimality restriction.')],[r'Write x=6a,y=6b with gcd(a,b)=1. The lcm condition gives ab=30.',r'Each prime 2,3,5 must go entirely into a or entirely into b; sharing would violate coprimality.',r'The three independent binary choices give $2^3=8$ ordered pairs.'],['Remove the specified gcd first.','Allocate each complete prime power to one of two coprime factors.'],'Translate gcd and lcm into coprime factor allocation.',lambda:sum(gcd(x,y)==6 and lcm(x,y)==180 for x in range(1,181) for y in range(1,181))),
q(13,r'Find the least positive integer n for which n/6 is an integer square and n/10 is an integer cube.',33750,[(1350,'Satisfy only one of the exponent congruences at the prime five.'),(6750,'Use an odd exponent of five for a square quotient.'),(27000,'Make n a cube without checking the two quotients.'),(900,'Make both quotients integers but not the required powers.')],[r'For the exponent e of 2 in n, e-1 must be divisible by both 2 and 3; the least choice is e=1.',r'At 3, e-1 must be even and e divisible by 3, so e=3. At 5, e must be even and e-1 divisible by 3, so e=4.',r'Other prime exponents can be zero. Thus $n=2\cdot3^3\cdot5^4=33750$; the quotients are $75^2$ and $15^3$.'],['Apply the square and cube requirements prime by prime.','Each prime has two simultaneous congruences for its exponent.'],'Combine perfect-power constraints through prime valuations.',lambda:next(6*k*k for k in range(1,1000) if any(6*k*k==10*j**3 for j in range(1,100))),method='Independent search through square multiples, checking cube multiples and the first attainable value.'),
q(14,r'For how many integers k does $t^2-kt+36$ have two distinct positive integer roots?',4,[(5,'Include the repeated root pair (6,6).'),(8,'Count both orders of the same roots.'),(9,'Count divisors rather than unordered factor pairs.'),(6,'Include a negative-root pair.')],[r'By Vieta, the roots have product 36 and sum k.',r'The distinct positive unordered pairs are (1,36),(2,18),(3,12),(4,9).',r'Their sums 37,20,15,13 are different, giving four values of k.'],['Replace the coefficient condition by a condition on the roots.','Enforce distinctness before counting possible sums.'],'Bridge a polynomial condition and integer factor pairs.',lambda:len({a+b for a in range(1,37) for b in range(a+1,37) if a*b==36}),level=2)]
e=[
q(101,r'How many positive integer pairs x≤y satisfy $xy+x+y=35$?',4,[(5,'Allow x=0.'),(9,'Ignore ordering and the zero endpoint.'),(3,'Exclude equal positive variables.'),(6,'Count all small integers as divisors.')],[r'The expression is almost a product: adding one gives $(x+1)(y+1)=36$. This is an equivalence, so every admissible factor pair recovers a solution.',r'Let a=x+1 and b=y+1. Positivity and ordering require $2\le a\le b$, excluding the factor pair (1,36).',r'The remaining pairs (2,18),(3,12),(4,9),(6,6) give four solutions.',r'Checking the boundary is essential: the equal pair corresponds to x=y=5 and is allowed. Merely halving the number of divisors would mishandle this case.'],['Add a constant to complete a product.','Translate positivity before listing factors.'],'Establish a bijection including its endpoint restrictions.',lambda:sum(x*y+x+y==35 for x in range(1,36) for y in range(x,36)),level=2),
q(102,r'How many nonnegative integer pairs satisfy $5x+7y=101$?',3,[(2,'Exclude the last feasible y.'),(4,'Let y extend beyond the nonnegative-x bound.'),(15,'Ignore the congruence restriction.'),(1,'Keep only the least residue representative.')],[r'Modulo 5, the equation is 2y≡1, giving y≡3 modulo 5. This step identifies a progression of candidates, not just y=3.',r'The bound 7y≤101 gives y≤14. Intersecting the progression with the interval leaves y=3,8,13.',r'These give x=16,9,2 respectively, so all three candidates are feasible.',r'A direct alternative is to start with one solution and note that every step y↦y+5 forces x↦x-7. The same nonnegative bounds stop the progression.'],['Reduce modulo one coefficient.','Keep every representative in the permitted interval.'],'Combine a residue class with bounds and reconstruct every solution.',lambda:sum(5*x+7*y==101 for x in range(21) for y in range(15)))]
finish('integer-constraints','Integer equations: factors, bounds & descent','Number theory','diophantine gcd algebra-transformations',26,'306–327',
 [r'Integer equations become finite when you find the right constraint. A product controls divisors, a residue controls possible remainders, and an inequality controls the search interval. The strongest solutions use these together instead of treating integer conditions as an afterthought.',r'Try the first worked example before reading its solution. The key move changes the equation into a correspondence between solutions and factor pairs. The counting comes only after the correspondence and its bounds are established.'],
 [section('Factor first, then translate every restriction',r'An expression xy+ax+by can be completed by adding ab, producing (x+b)(y+a). This changes an equation with two variables into a fixed product. To use the product as a counting device, prove both directions: each original solution gives a factor pair, and each admissible factor pair recovers an original solution.',r'The word admissible carries the work. Positive variables do not always imply positive shifted factors. Ordering may identify two reversed pairs; equal factors may be allowed or forbidden. A difference of squares adds a parity condition because x+y and x-y have the same parity. List these restrictions before applying a divisor count.',r'When an objective such as x+y must be minimized or maximized, the factorization still helps. Balanced positive factors minimize their sum, while distant integer factors often maximize it. But an objective involving a quotient may reverse which divisor you want. Exhibit an actual pair attaining the proposed bound.'),
 section('Use congruences to organize a finite search',r'For ax+by=N, reducing modulo a removes x. The resulting condition places y in one or more residue classes. Positivity or nonnegativity supplies a finite interval. Intersect the classes with that interval and recover x from the original equation; do not confuse the least residue with the only solution.',r'A digit equation adds sharp bounds because every digit lies between zero and nine, with a nonzero leading digit. Write place values explicitly, simplify, and compare the largest possible value of one side with the smallest possible value of the other. This can determine a leading digit before any casework.',r'For quadratic equations, residue tests often eliminate many candidates but are rarely sufficient. A number congruent to a square modulo five need not be an integer square. If a finite range remains, show why that range is exhaustive and then perform the exact square or factor test. A short complete search is a proof; an unexplained trial list is not.'),
 section('Prime exponents and descent',r'Perfect squares have even exponents at every prime; cubes have exponents divisible by three. Quotients such as n/6 change different prime exponents by different amounts. Solve the simultaneous exponent restrictions independently for each prime, then reconstruct the least number. Finally check the actual quotients and their positivity.',r'Gcd and lcm constraints invite a normalization. Divide both variables by their gcd. The reduced factors are coprime, so each full prime power in their product must belong to exactly one of them. This is why the number of distinct primes, rather than the total number of divisors, can govern the count.',r'Sometimes a congruence forces every variable to share a factor, and dividing by it leaves the same equation. A smallest positive solution would then yield a smaller positive solution. This contradiction is infinite descent. State what decreases and why it stays positive; a computer search over a large interval cannot replace that argument.')],
 ['Build reversible factorizations with explicit integer restrictions.','Combine residues, bounds, and feasibility checks.','Use prime exponents and descent to handle unbounded equations.'],
 [r'Expand $(x+b)(y+a)$ to identify the exact constant needed to complete the product.',r'For ax+by=N, derive the congruence and the interval separately, then intersect them.',r'To prove a minimum, show a lower bound and construct an admissible equality case.'],
 'A necessary divisibility or residue condition is not automatically sufficient. Recover the original variables and check their signs, ordering, and integrality.',e,p,
 dict(prompt=r'For positive integers x≤y with $1/x+1/y=1/4$, complete $(x-4)(y-4)=\square$ and count the solutions.',answer=r'The product is 16 and there are 3 pairs.',steps=[r'Multiplication and completion give $(x-4)(y-4)=16$, with both factors positive.',r'The smaller factor can be 1,2,4, giving (5,20),(6,12),(8,8).']),
 ['shifted factorization','bounded congruence search','prime-exponent constraints','infinite descent'],
 [(r'xy+ax+by+ab=(x+b)(y+a)','Product completion','turning a bilinear integer equation into a divisor problem','Translate sign, order, and nonzero restrictions to the shifted factors.'),(r'\gcd(x,y)\operatorname{lcm}(x,y)=xy','Gcd–lcm product','recovering a product from gcd and lcm data','x and y are positive integers; reduced factors after dividing by the gcd are coprime.'),(r'x^2-y^2=(x-y)(x+y)','Difference-of-squares factors','parametrizing integer solutions by factor pairs','The two factors must have the same parity to recover integer x and y.'),(r'v_p(n^k)=k\,v_p(n)','Perfect-power exponents','translating square and cube constraints into exponent congruences','p is prime; n is a positive integer and k is a positive integer.')], 'diophantine')
